dispatch_policy_final_v1125:
"""v1.12.5 最终调度收口。

在 dispatch_policy_v1125 的 Push/Pull 分流之上处理发布前边界：
- 没有逐集日期、但历史更新星期已经稳定时，仍把星期规则视为有效调度事实；
  不能误判“日历不可用”后回退为全量缺集主动搜索；
- 新订阅仍立即响应：先查频道缓存，必要时只合并强刷频道一次，再消费频道；
  频道后仅对当前更新日/电影待处理缺口进入主动完整资源链，未来集/非更新日不能因新增订阅绕门禁；
- 每小时 AiringDue 只处理今天应更新且仍未覆盖的媒体，并给这些媒体独立的 60 分钟外部检索窗口；
  执行仍复用既有完整链路：观影迅雷秒传 > 光鸭直接转存 > Magnet > ED2K；
- 每日 04:10 的自动强制 GYING 虽可绕过冷却执行本轮，但执行后必须登记冷却时间，
  避免 05:00 的小时 Pull 立刻再次访问观影；人工强制检查不受此规则影响；
- 04:10 的强制日历刷新延后到频道 + GYING 两阶段结束后，避免 TMDB/每日助手慢响应
  把本应最先执行的频道补漏阻塞在前面；
- 常规日历刷新若抛异常，60 秒内返回显式“不可用”哨兵，避免 selector 首次失败后
  每个订阅的 gate 又各自触发一次网络刷新形成故障风暴；
- Reliability 仍按订阅 ID 合并后台任务，但每个订阅额外保存真实 trigger；同一 worker 中同时到达
  频道 Push / Airing Pull / 新订阅时按真实来源重新分组，不能被第一个 worker trigger 串改执行模式；
- trigger 记录与 Governance/可靠性队列共用同一 RLock 完成原子入队，避免“刚判断未 active，下一瞬
  被其它线程抢先 active”后留下陈旧 trigger 污染下一轮；
- 频道故障恢复只恢复并消费频道，不得借恢复任务偷偷启动主动 GYING。

本层是标准 cooperative mixin，不继承预览策略类；运行时由显式 MRO 把它放在
GuangYaDispatchPolicyV1125Mixin 之前，所有 super() 都沿最终插件 MRO 继续下传。
"""
from __future__ import annotations

import datetime
import threading
import time
from typing import Any, Dict, Iterable, List


class GuangYaDispatchPolicyFinalV1125Mixin:
    """最终发布前调度权威。"""

    build_id = "20260904-r51"
    _calendar_failure_backoff_seconds_v1125 = 60
    _async_trigger_bucket_limit_v1125 = 8
    _hourly_due_cooldown_seconds_v1125 = 60 * 60

    def init_plugin(self, config: dict = None) -> None:
        self._dispatch_final_local_v1125 = threading.local()
        self._dispatch_trigger_lock_v1125 = threading.RLock()
        self._dispatch_triggers_v1125: Dict[int, List[str]] = {}
        self._calendar_refresh_failure_until_v1125 = 0.0
        self._calendar_refresh_failure_message_v1125 = ""
        return super().init_plugin(config)

    def _airing_gate_v1120(self, subscribe: Any, payload: Dict[str, Any] = None) -> Dict[str, Any]:
        result = dict(super()._airing_gate_v1120(subscribe, payload=payload) or {})
        if self._is_movie_subscription(subscribe) or bool(result.get("passive_channel_bypass_v1125")):
            return result

        # Weekly 层只有在历史样本达到置信门槛时才会给出 weekday。
        # 这已经足够说明“调度可判定”：今天命中则 due_uncovered 有值，非更新日则必须等待。
        # 不能因为当前缺集没有逐集 air_date 就退回 legacy 全量缺集搜索。
        if not bool(result.get("calendar_available")) and result.get("weekday") is not None:
            result["calendar_explicit_available_v1125"] = False
            result["calendar_available"] = True
            result["calendar_available_basis_v1125"] = "stable_weekday"
        return result

    def _external_cooldown_due_v1125(
        self,
        sid: int,
        state: Dict[str, Any],
        now: float,
    ) -> bool:
        """AiringDue 每小时只允许同一媒体进入一次主动资源复查窗口。"""
        row = dict(state.get(str(sid)) or {})
        try:
            last_at = float(row.get("last_at") or 0)
        except (TypeError, ValueError):
            last_at = 0.0
        cooldown = max(60, int(getattr(self, "_hourly_due_cooldown_seconds_v1125", 60 * 60) or 60 * 60))
        return not last_at or now - last_at >= cooldown

    def _record_auto_external_cooldown_v1125(self, subscribe: Any, origin: str) -> None:
        sid = int(getattr(subscribe, "id", 0) or 0)
        if sid <= 0:
            return
        try:
            state = dict(self._external_search_state_v1114() or {})
        except Exception:
            state = {}
        now = time.time()
        row = dict(state.get(str(sid)) or {})
        row.update({
            "last_at": now,
            "last_time": self._now_text(),
            "cooldown_minutes": int(getattr(self, "_external_search_cooldown_minutes_v1114", 180) or 180),
            "origin": str(origin or "automatic_force"),
        })
        state[str(sid)] = row
        if len(state) > 1000:
            state = dict(sorted(
                state.items(),
                key=lambda pair: float((pair[1] or {}).get("last_at") or 0),
                reverse=True,
            )[:1000])
        self.save_data("external_search_guard", state)

    def _claim_external_search_round_v1114(self, subscribe: Any, force: bool = False) -> bool:
        reader = getattr(self, "_route_source_mode_value_v1115", None)
        mode = str(reader() if callable(reader) else getattr(self, "_route_source_mode_v1115", "") or "")

        # AiringDue 已经由逐集日历/星期门禁证明“今天应该处理”。此时不能再套默认 180 分钟
        # external_search_guard，否则“每小时检查”实际会变成三小时才访问一次 GYING/迅雷。
        # 这里只把该模式收敛到 60 分钟；频道、人工、普通后台以及每日修复继续沿用原 Governance。
        if not force and mode == "airing_pull":
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid <= 0:
                return False
            try:
                state = dict(self._external_search_state_v1114() or {})
            except Exception:
                state = {}
            row = dict(state.get(str(sid)) or {})
            try:
                last_at = float(row.get("last_at") or 0)
            except (TypeError, ValueError):
                last_at = 0.0
            now = time.time()
            cooldown = max(60, int(getattr(self, "_hourly_due_cooldown_seconds_v1125", 60 * 60) or 60 * 60))
            allowed = not last_at or now - last_at >= cooldown
            self._external_round_allowed_v1114[sid] = allowed
            if allowed:
                state[str(sid)] = {
                    **row,
                    "last_at": now,
                    "last_time": self._now_text(),
                    "cooldown_minutes": max(1, int(cooldown / 60)),
                    "origin": "airing_full_chain_v1125",
                }
                if len(state) > 1000:
                    state = dict(sorted(
                        state.items(),
                        key=lambda pair: float((pair[1] or {}).get("last_at") or 0),
                        reverse=True,
                    )[:1000])
                self.save_data("external_search_guard", state)
            else:
                remaining = max(1, int((cooldown - (now - last_at)) / 60))
                self._plugin_log(
                    "INFO",
                    "【光鸭转存助手】【今日资源复查】#%s %s 本小时已执行过完整资源链，约 %s 分钟后再复查",
                    sid,
                    str(getattr(subscribe, "name", "") or ""),
                    remaining,
                )
            return allowed

        allowed = bool(super()._claim_external_search_round_v1114(subscribe, force=force))
        if not allowed or not force:
            return allowed
        if mode == "daily_repair_pull":
            self._record_auto_external_cooldown_v1125(subscribe, "daily_repair_pull")
        return allowed

    def _spawn_route_prime(self, sids: Iterable[int], trigger: str = "立即检查") -> None:
        """新增订阅只做一次频道补查；主动站点搜索仍交给最终日历 selector。"""
        ids = sorted(self._positive_ids_v1125(sids or []))
        if not ids or not self._enabled:
            return

        missing_cache: List[int] = []
        for sid in ids:
            subscribe = self._find_subscription(sid)
            if not subscribe or not self._is_guangya_route(subscribe):
                continue
            try:
                if not self._cached_matches_for_subscription(subscribe):
                    missing_cache.append(sid)
            except Exception:
                missing_cache.append(sid)

        if missing_cache:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【新订阅】%s 个订阅频道缓存未命中，合并现查频道一次；随后仅按更新日历判断是否主动搜索",
                len(missing_cache),
            )
            try:
                self.refresh_channels(force=True)
            except Exception as err:
                self._plugin_log(
                    "WARNING",
                    "【光鸭转存助手】【新订阅】频道现查失败，仍继续按当前更新日历判断主动搜索：%s",
                    str(err)[:260],
                )

        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【新订阅】进入频道缓存/现查 + 当前应播主动搜索判定，共 %s 个订阅",
            len(ids),
        )
        self._queue_async_route_check(ids, trigger="新订阅资源匹配")

    # ------------------------------------------------------------------
    # 异步队列来源保持：Reliability 合并 ID，但不能合并掉每个 ID 的来源语义。
    # ------------------------------------------------------------------
    def _queue_async_route_check(self, sids: Iterable[int], trigger: str = "后台检查") -> None:
        ids = sorted(self._positive_ids_v1125(sids or []))
        if not ids or not bool(getattr(self, "_enabled", False)):
            return
        current = getattr(self, "_runtime_is_current", None)
        if callable(current) and not bool(current()):
            return

        # _async_route_lock 在 Experience 初始化为 RLock。整个“看 active -> 记录 trigger ->
        # Governance 再过滤 -> Reliability 入 pending/recheck”都在同一把锁里完成；后续 super
        # 会可重入地拿同一 RLock，因此不会在预测与真正入队之间被 worker 改写 active。
        route_lock = getattr(self, "_async_route_lock", None)
        if route_lock is None:
            route_lock = threading.RLock()
            self._async_route_lock = route_lock

        with route_lock:
            accepted = set(ids)
            automatic = getattr(self, "_automatic_trigger_v1114", None)
            manual = getattr(self, "_manual_trigger_v1114", None)
            is_automatic = bool(automatic(trigger)) if callable(automatic) else False
            is_manual = bool(manual(trigger)) if callable(manual) else False
            if is_automatic and not is_manual:
                active = set(getattr(self, "_async_route_active", set()) or set())
                accepted -= active

            if accepted:
                lock = getattr(self, "_dispatch_trigger_lock_v1125", None)
                if lock is None:
                    lock = threading.RLock()
                    self._dispatch_trigger_lock_v1125 = lock
                store = getattr(self, "_dispatch_triggers_v1125", None)
                if not isinstance(store, dict):
                    store = {}
                    self._dispatch_triggers_v1125 = store
                text = str(trigger or "后台检查")
                with lock:
                    for sid in sorted(accepted):
                        bucket = list(store.get(sid) or [])
                        # Reliability finally 的“后台合并补偿”只是内部重拉起标识；真实来源还在桶中时
                        # 绝不能覆盖成 generic trigger。
                        if text == "后台合并补偿" and bucket:
                            continue
                        if text not in bucket:
                            bucket.append(text)
                        limit = max(2, int(getattr(self, "_async_trigger_bucket_limit_v1125", 8) or 8))
                        store[sid] = bucket[-limit:]

            return super()._queue_async_route_check(ids, trigger=trigger)

    @staticmethod
    def _ordered_async_triggers_v1125(values: Iterable[str], fallback: str) -> List[str]:
        rows: List[str] = []
        for raw in values or []:
            value = str(raw or "").strip()
            if value and value not in rows:
                rows.append(value)
        if not rows:
            rows = [str(fallback or "后台检查")]

        # 新订阅任务自己已经包含“频道 -> 当前应播 Pull”，同一 debounce 内的普通频道/日历
        # 自动触发无需再重复；显式人工操作保留。
        prime = next((value for value in rows if "新订阅资源匹配" in value), "")
        if prime:
            manual_rows = [
                value for value in rows
                if any(token in value.lower() for token in ("手动", "人工", "立即", "api", "控制台", "按钮"))
            ]
            return [prime, *[value for value in manual_rows if value != prime]]

        recovery = next((value for value in rows if "频道故障自动恢复" in value), "")
        channel = [value for value in rows if "频道新增资源" in value]
        active = [
            value for value in rows
            if "观影定时轮询" in value or "更新日历" in value or "airing" in value.lower()
        ]
        others = [value for value in rows if value not in channel and value not in active and value != recovery]
        ordered: List[str] = []
        # 被动资源先消费，再允许主动 Pull 重算真实缺口。
        if recovery:
            ordered.append(recovery)
        else:
            ordered.extend(channel)
        ordered.extend(active)
        ordered.extend(others)
        return ordered or [str(fallback or "后台检查")]

    def _take_async_route_triggers_v1125(self, batch: Iterable[int], fallback: str) -> Dict[int, List[str]]:
        ids = sorted(self._positive_ids_v1125(batch or []))
        store = getattr(self, "_dispatch_triggers_v1125", None)
        lock = getattr(self, "_dispatch_trigger_lock_v1125", None)
        if not isinstance(store, dict) or lock is None:
            return {sid: [str(fallback or "后台检查")] for sid in ids}
        result: Dict[int, List[str]] = {}
        with lock:
            for sid in ids:
                values = list(store.pop(sid, []) or [])
                result[sid] = self._ordered_async_triggers_v1125(values, fallback)
        return result

    @staticmethod
    def _async_trigger_priority_v1125(trigger: str) -> int:
        text = str(trigger or "")
        if "频道故障自动恢复" in text or "频道新增资源" in text:
            return 0
        if "新订阅资源匹配" in text or "外部补搜" in text:
            return 1
        if "观影定时轮询" in text or "更新日历" in text or "airing" in text.lower():
            return 2
        return 3

    def _run_dispatch_trigger_v1125(self, ids: List[int], trigger: str) -> None:
        text = str(trigger or "")
        if not ids:
            return None

        if "频道故障自动恢复" in text:
            # 这是频道 transport 的恢复任务，不是主动资源站调度器。恢复成功后只消费频道缓存；
            # 常规 GYING 仍等 AiringDue/日历 selector。
            try:
                self.refresh_channels(force=True)
            except Exception as err:
                self._plugin_log(
                    "WARNING",
                    "【光鸭转存助手】【频道恢复】恢复刷新仍失败，继续仅使用频道缓存，不启动 GYING：%s",
                    str(err)[:260],
                )
            return self._run_v1115_mode_batch(ids, text, "channel_event", force=False)

        if "外部补搜" in text:
            return self._run_v1115_mode_batch(ids, text, "airing_pull", force=True)

        if "新订阅资源匹配" in text:
            self._run_v1115_mode_batch(
                ids,
                "新订阅资源匹配·频道阶段",
                "channel_event",
                force=False,
            )
            remaining: List[int] = []
            checker = getattr(self, "_manual_remaining_ids_v11211", None)
            if callable(checker):
                remaining = list(checker(ids) or [])
            else:
                remaining = list(ids)
            if remaining:
                self._run_v1115_mode_batch(
                    remaining,
                    "新订阅资源匹配·外部补搜",
                    "airing_pull",
                    force=True,
                )
            return None

        return super()._run_reliability_route_batch(ids, text)

    def _run_reliability_route_batch(self, batch: List[int], trigger: str) -> None:
        ids = sorted(self._positive_ids_v1125(batch or []))
        if not ids:
            return None
        trigger_map = self._take_async_route_triggers_v1125(ids, trigger)
        groups: Dict[str, List[int]] = {}
        for sid in ids:
            for value in trigger_map.get(sid) or [str(trigger or "后台检查")]:
                groups.setdefault(str(value or "后台检查"), []).append(sid)

        for value in sorted(groups, key=lambda item: (self._async_trigger_priority_v1125(item), item)):
            group_ids = sorted(set(groups.get(value) or []))
            self._run_dispatch_trigger_v1125(group_ids, value)
        return None

    def _calendar_failure_payload_v1125(self) -> Dict[str, Any]:
        """必须保持 truthy，避免下层 `payload or refresh()` 再次发起网络请求。"""
        return {
            "updated_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "subscriptions": [],
            "count": 0,
            "calendar_refresh_failed_v1125": True,
            "errors": [str(getattr(self, "_calendar_refresh_failure_message_v1125", "") or "calendar unavailable")[:240]],
        }

    def _refresh_airing_calendar_v1120(self, force: bool = False) -> Dict[str, Any]:
        """每日阶段支持延迟强刷；普通刷新异常进入短退避，防止每订阅重复打日历服务。"""
        local = getattr(self, "_dispatch_final_local_v1125", None)
        if (
            force
            and local is not None
            and bool(getattr(local, "defer_daily_calendar", False))
        ):
            cached = self.get_data("airing_calendar_v1120") or {}
            if isinstance(cached, dict) and cached:
                return dict(cached)
            return self._calendar_failure_payload_v1125()

        if force:
            return dict(super()._refresh_airing_calendar_v1120(force=True) or {})

        now = time.time()
        try:
            failure_until = float(getattr(self, "_calendar_refresh_failure_until_v1125", 0.0) or 0.0)
        except (TypeError, ValueError):
            failure_until = 0.0
        if failure_until > now:
            return self._calendar_failure_payload_v1125()

        try:
            result = dict(super()._refresh_airing_calendar_v1120(force=False) or {})
        except Exception as err:
            self._calendar_refresh_failure_until_v1125 = now + max(
                15,
                int(getattr(self, "_calendar_failure_backoff_seconds_v1125", 60) or 60),
            )
            self._calendar_refresh_failure_message_v1125 = str(err)[:240]
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【更新日历】常规刷新异常，进入短退避避免按订阅重复请求：%s",
                str(err)[:240],
            )
            return self._calendar_failure_payload_v1125()

        self._calendar_refresh_failure_until_v1125 = 0.0
        self._calendar_refresh_failure_message_v1125 = ""
        return result

    def _daily_full_catchup_v1110(self) -> Dict[str, Any]:
        """严格执行频道 -> 剩余 GYING -> 日历刷新，不让日历网络请求挡在频道前。"""
        local = getattr(self, "_dispatch_final_local_v1125", None)
        if local is None:
            local = threading.local()
            self._dispatch_final_local_v1125 = local
        previous = bool(getattr(local, "defer_daily_calendar", False))
        local.defer_daily_calendar = True
        try:
            result = super()._daily_full_catchup_v1110()
        finally:
            local.defer_daily_calendar = previous

        try:
            self._refresh_airing_calendar_v1120(force=True)
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【每日全员复核】两阶段补漏已完成，但末尾更新日历刷新失败：%s",
                str(err)[:260],
            )
        return result


__all__ = ["GuangYaDispatchPolicyFinalV1125Mixin"]

dispatch_policy_v1125:
"""v1.12.5：频道 Push / 观影 Pull 调度收口层。

原则：
- 5 分钟 tick 只负责频道增量，不再同时启动主动 GYING；
- 频道是被动到达的资源，命中真实缺集后不受播出日期门禁限制，也不依赖日历服务可用，
  但仍受媒体身份、reservation/source claim、episode fence 与质量门禁限制；频道批次继续禁止主动 GYING；
- 主动 GYING 只由更新日历服务统一驱动：TV/动漫先按 due_uncovered 过滤，电影按外部
  检索冷却参与；日历不可用时才退回旧的“真实缺集 + 冷却”语义；
- 每天 04:10 全员复核改为两阶段：先用频道缓存/现查补全，再只对仍未覆盖且不在途的
  订阅做一次强制 GYING 补漏，避免频道已有资源时仍先打观影服务器；
- due scope 改为线程局部上下文，避免频道、日历、人工任务并发处理不同订阅时互相串集数范围。

这个层只改“什么时候触发哪个来源”和调度上下文隔离，不改变迅雷 JSON、媒体身份、资源质量、
Episode Resolver、光鸭转存/cloudcollection 与 MoviePilot 完成事实的既有实现。
"""
from __future__ import annotations

import datetime
import threading
import time
from contextlib import contextmanager
from typing import Any, Dict, Iterable, List, Optional, Set, Tuple


class GuangYaDispatchPolicyV1125Mixin:
    """最终触发策略：频道被动消费、日历主动拉取、每日两阶段修复。"""

    build_id = "20260904-r51"

    def init_plugin(self, config: dict = None) -> None:
        # 两类线程局部状态分别保护：
        # 1) 5 分钟 tick 只抑制当前 tick 线程的旧 viewing poll；
        # 2) due scope 只约束当前来源执行线程，不能串到另一个订阅线程。
        self._dispatch_tick_local_v1125 = threading.local()
        self._airing_scope_local_v1125 = threading.local()
        return super().init_plugin(config)

    @staticmethod
    def _positive_ids_v1125(values: Iterable[Any]) -> Set[int]:
        result: Set[int] = set()
        for raw in values or []:
            try:
                value = int(raw or 0)
            except (TypeError, ValueError):
                continue
            if value > 0:
                result.add(value)
        return result

    # ------------------------------------------------------------------
    # due scope 并发隔离
    # ------------------------------------------------------------------
    def _airing_scope_local_value_v1125(self):
        local = getattr(self, "_airing_scope_local_v1125", None)
        if local is None:
            local = threading.local()
            self._airing_scope_local_v1125 = local
        return local

    @contextmanager
    def _due_scope_v1120(self, subscribe: Any, episodes: Iterable[int]):
        local = self._airing_scope_local_value_v1125()
        had_scope = hasattr(local, "scope")
        previous = getattr(local, "scope", None)
        local.scope = {
            "subscribe_id": int(getattr(subscribe, "id", 0) or 0),
            "episodes": sorted(self._positive_ids_v1125(episodes)),
        }
        try:
            yield
        finally:
            if had_scope:
                local.scope = previous
            else:
                try:
                    delattr(local, "scope")
                except AttributeError:
                    pass

    @contextmanager
    def _without_due_scope_v1120(self):
        local = self._airing_scope_local_value_v1125()
        had_scope = hasattr(local, "scope")
        previous = getattr(local, "scope", None)
        local.scope = None
        try:
            yield
        finally:
            if had_scope:
                local.scope = previous
            else:
                try:
                    delattr(local, "scope")
                except AttributeError:
                    pass

    def _subscription_missing_episodes(self, subscribe: Any) -> List[int]:
        # 下层 scheduler 的历史共享 scope 在最终运行时始终保持 None；最终裁剪只认本层 thread-local。
        values = sorted(self._positive_ids_v1125(super()._subscription_missing_episodes(subscribe) or []))
        local = self._airing_scope_local_value_v1125()
        scope = getattr(local, "scope", None)
        if not isinstance(scope, dict):
            return values
        sid = int(getattr(subscribe, "id", 0) or 0)
        if sid != int(scope.get("subscribe_id") or 0):
            return values
        allowed = self._positive_ids_v1125(scope.get("episodes") or [])
        return [value for value in values if value in allowed]

    def _active_selected_subscriptions_v1125(self) -> List[Any]:
        selected = self._positive_ids_v1125(getattr(self, "_selected_subscriptions", []) or [])
        rows: List[Any] = []
        for subscribe in self._list_subscriptions("N,R") or []:
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid <= 0 or sid not in selected:
                continue
            try:
                if not self._is_guangya_route(subscribe):
                    continue
            except Exception:
                continue
            rows.append(subscribe)
        return rows

    def _uncovered_missing_v1125(self, subscribe: Any) -> Set[int]:
        if self._is_movie_subscription(subscribe):
            return set()
        try:
            with self._without_due_scope_v1120():
                missing = self._positive_ids_v1125(self._subscription_missing_episodes(subscribe) or [])
        except Exception:
            missing = set()
        if not missing:
            return set()
        try:
            reservations = dict(self._pending_reservations(subscribe) or {})
            reserved = self._positive_ids_v1125(reservations.get("episodes") or [])
        except Exception:
            reserved = set()
        sid = int(getattr(subscribe, "id", 0) or 0)
        try:
            claimed = self._positive_ids_v1125(self._active_source_claims(sid) or [])
        except Exception:
            claimed = set()
        return missing - reserved - claimed

    def _movie_needs_pull_v1125(self, subscribe: Any) -> bool:
        if not self._is_movie_subscription(subscribe):
            return False
        confirmed = getattr(self, "_movie_transfer_confirmed", None)
        if callable(confirmed):
            try:
                if bool(confirmed(subscribe)):
                    try:
                        self._finish_subscription_if_complete(subscribe)
                    except Exception:
                        pass
                    return False
            except Exception:
                pass
        try:
            reservations = dict(self._pending_reservations(subscribe) or {})
            if bool(reservations.get("movie")):
                return False
        except Exception:
            pass
        return str(getattr(subscribe, "state", "") or "") in {"N", "R", ""}

    # ------------------------------------------------------------------
    # 频道 Push：日期只控制主动搜索；被动资源完全不依赖日历服务。
    # ------------------------------------------------------------------
    def _airing_gate_v1120(self, subscribe: Any, payload: Dict[str, Any] = None) -> Dict[str, Any]:
        if self._is_movie_subscription(subscribe):
            return dict(super()._airing_gate_v1120(subscribe, payload=payload) or {})

        mode_reader = getattr(self, "_route_source_mode_value_v1115", None)
        mode = str(mode_reader() if callable(mode_reader) else getattr(self, "_route_source_mode_v1115", "") or "")
        if mode != "channel_event":
            return dict(super()._airing_gate_v1120(subscribe, payload=payload) or {})

        # 被动频道资源已经到达，本轮只需要 MoviePilot 真实缺集与在途事实；
        # 不调用 super 的日历门禁，DailyAssistant/TMDB 故障也不能阻塞已到达资源。
        try:
            with self._without_due_scope_v1120():
                raw_missing = self._positive_ids_v1125(self._subscription_missing_episodes(subscribe) or [])
        except Exception:
            raw_missing = set()
        try:
            reservations = dict(self._pending_reservations(subscribe) or {})
            reserved = self._positive_ids_v1125(reservations.get("episodes") or [])
        except Exception:
            reserved = set()
        sid = int(getattr(subscribe, "id", 0) or 0)
        try:
            claimed = self._positive_ids_v1125(self._active_source_claims(sid) or [])
        except Exception:
            claimed = set()
        reserved &= raw_missing
        claimed &= raw_missing
        passive_uncovered = raw_missing - reserved - claimed

        # 仅把最近一次严格日历快照作为诊断信息，不让它参与频道准入。
        strict_state = self.get_data("airing_gate_state_v1120") or {}
        strict_row = dict(strict_state.get(str(sid)) or {}) if isinstance(strict_state, dict) else {}
        return {
            "subscribe_id": sid,
            "name": str(getattr(subscribe, "name", "") or ""),
            "calendar_available": True,
            "calendar_provider": str(strict_row.get("calendar_provider") or "passive_channel"),
            "raw_missing": sorted(raw_missing),
            "due_missing": sorted(raw_missing),
            "due_uncovered": sorted(passive_uncovered),
            "reserved": sorted(reserved),
            "claimed": sorted(claimed),
            "future_missing": [],
            "unscheduled_missing": [],
            "off_day_missing": [],
            "covered": not bool(passive_uncovered),
            "next_episode": int(strict_row.get("next_episode") or 0),
            "next_air_at": str(strict_row.get("next_air_at") or ""),
            "next_precision": str(strict_row.get("next_precision") or ""),
            "passive_channel_bypass_v1125": True,
            "strict_due_uncovered_v1125": list(strict_row.get("due_uncovered") or []),
            "strict_future_missing_v1125": list(strict_row.get("future_missing") or []),
            "strict_off_day_missing_v1125": list(strict_row.get("off_day_missing") or []),
            "checked_at": datetime.datetime.now().isoformat(timespec="seconds"),
        }

    # ------------------------------------------------------------------
    # 5 分钟 tick：只保留频道刷新/事件匹配，旧 viewing poll 在本线程内返回空。
    # ------------------------------------------------------------------
    def _tick_local_v1125(self):
        local = getattr(self, "_dispatch_tick_local_v1125", None)
        if local is None:
            local = threading.local()
            self._dispatch_tick_local_v1125 = local
        return local

    def _tick(self, host_service: bool = True) -> None:
        local = self._tick_local_v1125()
        previous = bool(getattr(local, "channel_only", False))
        local.channel_only = True
        try:
            return super()._tick(host_service=host_service)
        finally:
            local.channel_only = previous

    # ------------------------------------------------------------------
    # 单一主动 Pull 选择器：先冷却，再日历；日历不可用才退回旧缺集语义。
    # ------------------------------------------------------------------
    def _external_cooldown_due_v1125(
        self,
        sid: int,
        state: Dict[str, Any],
        now: float,
    ) -> bool:
        row = dict(state.get(str(sid)) or {})
        try:
            last_at = float(row.get("last_at") or 0)
        except (TypeError, ValueError):
            last_at = 0.0
        try:
            cooldown = max(900, int(getattr(self, "_external_search_cooldown_minutes_v1114", 180) or 180) * 60)
        except (TypeError, ValueError):
            cooldown = 180 * 60
        return not last_at or now - last_at >= cooldown

    def _smart_pull_due_ids_v1125(self) -> List[int]:
        rows = self._active_selected_subscriptions_v1125()
        try:
            state = dict(self._external_search_state_v1114() or {})
        except Exception:
            state = {}
        now = time.time()

        cooldown_rows: List[Any] = []
        for subscribe in rows:
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid > 0 and self._external_cooldown_due_v1125(sid, state, now):
                cooldown_rows.append(subscribe)

        # 没有任何订阅达到外部冷却时，不刷新日历，也不做额外媒体查询。
        if not cooldown_rows:
            return []

        calendar: Optional[Dict[str, Any]] = None
        if any(not self._is_movie_subscription(subscribe) for subscribe in cooldown_rows):
            try:
                calendar = dict(self._refresh_airing_calendar_v1120(force=False) or {})
            except Exception:
                calendar = None

        due: List[int] = []
        fallback = 0
        off_day = 0
        for subscribe in cooldown_rows:
            sid = int(getattr(subscribe, "id", 0) or 0)
            if sid <= 0:
                continue
            if self._is_movie_subscription(subscribe):
                if self._movie_needs_pull_v1125(subscribe):
                    due.append(sid)
                continue

            uncovered = self._uncovered_missing_v1125(subscribe)
            if not uncovered:
                try:
                    with self._without_due_scope_v1120():
                        if not self._subscription_missing_episodes(subscribe):
                            self._finish_subscription_if_complete(subscribe)
                except Exception:
                    pass
                continue

            try:
                if calendar is not None:
                    gate = dict(self._airing_gate_v1120(subscribe, payload=calendar) or {})
                else:
                    gate = dict(self._airing_gate_v1120(subscribe) or {})
            except Exception:
                gate = {}

            if bool(gate.get("calendar_available")):
                if self._positive_ids_v1125(gate.get("due_uncovered") or []):
                    due.append(sid)
                else:
                    off_day += 1
                continue

            # 与既有 scheduler 保持一致：日历完全不可用时不能冻结追更，退回真实缺集 + 冷却。
            fallback += 1
            due.append(sid)

        try:
            self.save_data("dispatch_policy_v1125", {
                "selector_at": datetime.datetime.now().isoformat(timespec="seconds"),
                "active": len(rows),
                "cooldown_due": len(cooldown_rows),
                "pull_due": len(due),
                "off_day": off_day,
                "calendar_fallback": fallback,
            })
        except Exception:
            pass
        return sorted(set(due))

    def _viewing_due_subscription_ids_v1115(self) -> List[int]:
        local = self._tick_local_v1125()
        if bool(getattr(local, "channel_only", False)):
            return []
        return self._smart_pull_due_ids_v1125()

    # 频道消息的异步 worker 结束后不再追加一次主动观影；历史遗留的“观影定时轮询”
    # 若仍进入队列，也必须重新经过当前智能 selector，不能按旧大列表直接执行。
    def _run_reliability_route_batch(self, batch: List[int], trigger: str) -> None:
        text = str(trigger or "")
        normalized = sorted(self._positive_ids_v1125(batch or []))
        if "频道新增资源" in text:
            if normalized:
                return self._run_v1115_mode_batch(normalized, trigger, "channel_event", force=False)
            return None
        if "观影定时轮询" in text:
            allowed = set(self._smart_pull_due_ids_v1125())
            filtered = [sid for sid in normalized if sid in allowed]
            if filtered:
                return self._run_v1115_mode_batch(filtered, "更新日历主动拉取", "airing_pull", force=False)
            return None
        return super()._run_reliability_route_batch(batch, trigger)

    # ------------------------------------------------------------------
    # 每小时 AiringDue：唯一常规主动 GYING 时钟，严格服从外部检索冷却。
    # ------------------------------------------------------------------
    def _calendar_due_check_v1110(self) -> Dict[str, Any]:
        active = self._active_selected_subscriptions_v1125()
        due_ids = self._smart_pull_due_ids_v1125()
        now_text = datetime.datetime.now().isoformat(timespec="seconds")
        state = self.get_data("airing_check_state_v1110") or {}
        if not isinstance(state, dict):
            state = {}

        results: List[Dict[str, Any]] = []
        for sid in due_ids:
            subscribe = self._find_subscription(sid)
            episodes: List[int] = []
            if subscribe and not self._is_movie_subscription(subscribe):
                try:
                    gate = dict(self._airing_gate_v1120(subscribe) or {})
                    episodes = sorted(self._positive_ids_v1125(gate.get("due_uncovered") or []))
                except Exception:
                    episodes = []
            state[str(sid)] = {
                "checked_at": now_text,
                "episodes": episodes,
                "mode": "airing_pull",
            }
            results.append({
                "subscribe_id": sid,
                "episodes": episodes,
                "scheduled": True,
                "mode": "airing_pull",
            })
        if len(state) > 1000:
            state = dict(list(state.items())[-1000:])
        self.save_data("airing_check_state_v1110", state)

        if due_ids:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【主动拉取】日历/电影冷却筛选后执行 %s 个订阅；5 分钟频道 tick 不再启动 GYING",
                len(due_ids),
            )
            self._run_v1115_mode_batch(
                due_ids,
                "更新日历主动拉取",
                "airing_pull",
                force=False,
            )
        return {
            "success": True,
            "checked": len(due_ids),
            "skipped": max(0, len(active) - len(due_ids)),
            "results": results,
            "mode": "single_airing_pull",
        }

    # ------------------------------------------------------------------
    # 每日 04:10：频道优先全量修复 -> 重算真实缺口 -> 仅剩余项 GYING 强制补漏。
    # ------------------------------------------------------------------
    def _repair_signature_v1125(self, subscribe: Any) -> Tuple[int, ...] | Tuple[str]:
        if self._is_movie_subscription(subscribe):
            return ("movie",) if self._movie_needs_pull_v1125(subscribe) else tuple()
        try:
            with self._without_due_scope_v1120():
                return tuple(sorted(self._positive_ids_v1125(self._subscription_missing_episodes(subscribe) or [])))
        except Exception:
            return tuple()

    def _daily_full_catchup_v1110(self) -> Dict[str, Any]:
        started = datetime.datetime.now()
        try:
            self.refresh_channels(force=True)
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【每日全员复核】频道强制刷新失败，继续使用缓存：%s",
                str(err)[:260],
            )
        try:
            self._refresh_airing_calendar_v1120(force=True)
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【每日全员复核】更新日历刷新失败，仍继续两阶段修复：%s",
                str(err)[:260],
            )

        initial_rows = self._active_selected_subscriptions_v1125()
        initial_ids = [int(getattr(subscribe, "id", 0) or 0) for subscribe in initial_rows]
        before: Dict[int, Tuple[Any, ...]] = {}
        names: Dict[int, str] = {}
        for subscribe in initial_rows:
            sid = int(getattr(subscribe, "id", 0) or 0)
            names[sid] = str(getattr(subscribe, "name", "") or "")
            try:
                sync = getattr(self, "_sync_media_library_progress", None)
                if callable(sync):
                    sync(subscribe)
            except Exception:
                pass
            fresh = self._find_subscription(sid) or subscribe
            before[sid] = tuple(self._repair_signature_v1125(fresh))

        # 第一阶段只消费频道现有资源；channel_event 会关闭 GYING，并由本层绕过日期门禁。
        if initial_ids:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【每日全员复核】阶段1：%s 个订阅先消费频道资源，不访问 GYING",
                len(initial_ids),
            )
            self._run_v1115_mode_batch(
                initial_ids,
                "每日全员复核·频道阶段",
                "channel_event",
                force=False,
            )

        # 重新读取成功回执 / reservation / source claim，只让真正仍未覆盖的订阅进入主动搜索。
        remaining: List[int] = []
        after_channel: Dict[int, Tuple[Any, ...]] = {}
        for subscribe in self._active_selected_subscriptions_v1125():
            sid = int(getattr(subscribe, "id", 0) or 0)
            fresh = self._find_subscription(sid) or subscribe
            after_channel[sid] = tuple(self._repair_signature_v1125(fresh))
            if self._is_movie_subscription(fresh):
                if self._movie_needs_pull_v1125(fresh):
                    remaining.append(sid)
                continue
            if self._uncovered_missing_v1125(fresh):
                remaining.append(sid)

        if remaining:
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【每日全员复核】阶段2：频道后仍有 %s 个订阅存在未覆盖缺口，才进入 GYING 强制补漏",
                len(remaining),
            )
            self._run_v1115_mode_batch(
                remaining,
                "每日全员复核·GYING阶段",
                "daily_repair_pull",
                force=True,
            )

        final_rows = {int(getattr(subscribe, "id", 0) or 0): subscribe for subscribe in self._active_selected_subscriptions_v1125()}
        results: List[Dict[str, Any]] = []
        failed = changed = 0
        remaining_set = set(remaining)
        for sid in initial_ids:
            subscribe = final_rows.get(sid) or self._find_subscription(sid)
            if subscribe:
                final_signature = tuple(self._repair_signature_v1125(subscribe))
                if self._is_movie_subscription(subscribe):
                    still_needs = self._movie_needs_pull_v1125(subscribe)
                else:
                    still_needs = bool(self._uncovered_missing_v1125(subscribe))
            else:
                final_signature = tuple()
                still_needs = False
            if before.get(sid, tuple()) != final_signature:
                changed += 1
            if still_needs:
                failed += 1
            results.append({
                "subscribe_id": sid,
                "name": names.get(sid, ""),
                "missing_before": list(before.get(sid, tuple())),
                "missing_after_channel": list(after_channel.get(sid, tuple())),
                "missing_after": list(final_signature),
                "gying_attempted": sid in remaining_set,
                "success": not still_needs,
            })

        payload = {
            "started_at": started.isoformat(timespec="seconds"),
            "finished_at": datetime.datetime.now().isoformat(timespec="seconds"),
            "checked": len(initial_ids),
            "channel_phase": len(initial_ids),
            "gying_phase": len(remaining),
            "changed": changed,
            "failed": failed,
            "results": results[-200:],
            "strategy": "channel_first_then_gying",
        }
        self.save_data("daily_catchup_v1110", payload)
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【每日全员复核】完成：订阅=%s 频道阶段=%s GYING阶段=%s 仍需补漏=%s",
            payload["checked"],
            payload["channel_phase"],
            payload["gying_phase"],
            payload["failed"],
        )
        return {
            "success": True,
            "data": payload,
            "message": f"已复核 {payload['checked']} 个订阅；仅 {payload['gying_phase']} 个进入 GYING 补漏",
        }


__all__ = ["GuangYaDispatchPolicyV1125Mixin"]

empty_dir_guard_v11218:
"""v1.12.18：阻止失败/只读检查在光鸭云盘留下空目录。

本层只收口目录生命周期，不改变任何媒体身份、缺集、来源优先级或落盘规则。

核心原则：
1. ``GuangYaApi.get_folder`` 是 get-or-create，不能用于纯验证；恢复待落盘任务时只用
   ``get_item`` 查询目标目录，目录不存在即判定尚未落盘，绝不为了“检查”创建目录；
2. Magnet/ED2K 在第一次创建目标目录之前先完成 ``resolve_res`` 与文件选择；解析失败
   直接沿用原失败状态机，不创建任何目标目录；
3. 迅雷、光鸭分享以及 cloudcollection 真正写入前如果必须创建目录，只记录“本次调用前
   明确不存在”的目录；失败且没有服务端 taskId 时，才允许清理这些本次新建目录；
4. 清理前重新读取远端目录并列目录。已有目录、非空目录、读取失败、任务已经提交、
   ``/`` 与用户配置的保存根目录一律不删除；
5. 删除按最深层优先，只使用光鸭存储 API 的正常 delete，任何事实不确定都 fail closed。
"""
from __future__ import annotations

import threading
from pathlib import Path
from typing import Any, Dict, Iterable, List, Tuple

from .legacy import _normalize_config_path, _safe_relative_path
from .search_recall_v11217 import GuangYaSearchRecallV11217Mixin


class GuangYaEmptyDirGuardV11218Mixin(GuangYaSearchRecallV11217Mixin):
    """为四种写盘来源提供统一的“只在真正写入时建目录”边界。"""

    plugin_version = "1.12.18"
    build_id = "20260906-r65"

    # ------------------------------------------------------------------
    # 线程本地目录事务
    # ------------------------------------------------------------------
    def _dir_guard_local_v11218(self) -> threading.local:
